from pathlib import Path
from html import escape
import json,re,shutil
from docx import Document
from docx.oxml.ns import qn
ROOT=Path(__file__).resolve().parents[1]
DOC=ROOT/'documentos'
def convert(src):
 d=Document(src);lines=[]
 for el in d.element.body:
  if el.tag==qn('w:p'):
   from docx.text.paragraph import Paragraph
   p=Paragraph(el,d);txt=p.text.strip()
   if not txt:continue
   st=p.style.name
   prefix='# ' if st=='Title' else '## ' if st=='Heading 1' else '### ' if st=='Heading 2' else ''
   lines.extend([prefix+txt,''])
  elif el.tag==qn('w:tbl'):
   from docx.table import Table
   rows=[[c.text.replace('\n','<br>').replace('|','\\|') for c in row.cells] for row in Table(el,d).rows]
   lines.append('| '+' | '.join(rows[0])+' |');lines.append('| '+' | '.join(['---']*len(rows[0]))+' |')
   lines.extend('| '+' | '.join(row)+' |' for row in rows[1:]);lines.append('')
 return '\n'.join(lines)
for name in ['CV','DESIGN']:(ROOT/(name+'.md')).write_text(convert(DOC/(name+'.docx')))
